insert or replace into LocalizedText (Language,  Tag,    Text)
values
-- Civs
    -- Abbasid
    ("en_US",  "LOC_BUILDING_MADRASA_DESCRIPTION",   "Abbasid [TIP:LOC_PEDIA_CONCEPTS_UNIQUE_BUILDING_TOOLTIP]Unique Science Building[/TIP]. +6[icon:YIELD_SCIENCE] Science. +0.5[icon:YIELD_SCIENCE] Science Adjacency for [TIP:LOC_PEDIA_CONCEPTS_DISTRICT_TOOLTIP]Quarters[/TIP], Science [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP] and +1[icon:YIELD_SCIENCE] Science Adjacency for [TIP:LOC_PEDIA_CONCEPTS_WONDERS_TOOLTIP]Wonders[/TIP]."),
    -- Bulgaria
    ("en_US",  "LOC_TRADITION_STRATAGEMS_DESCRIPTION",   "+50% Yield and [icon:Action_Heal] HP from [icon:Action_Pillage] Pillaging. [B]+5 [icon:NAR_REW_COMBAT] [TIP:LOC_PEDIA_CONCEPTS_COMBAT_STRENGTH_TOOLTIP]Combat Strength[/TIP][/B] for [icon:UNIT_CLASS_INFANTRY] Infantry and [icon:UNIT_CLASS_CAVALRY] [TIP:LOC_PEDIA_CONCEPTS_CAVALRY_UNITS_TOOLTIP]Cavalry[/TIP] against other [TIP:LOC_PEDIA_CONCEPTS_LAND_UNITS_TOOLTIP]Land Units[/TIP] when you have at least [B]4 [icon:NAR_REW_GREATWORK] [TIP:LOC_PEDIA_CONCEPTS_GREAT_WORKS_TOOLTIP]Great Works[/TIP][/B] on display."),
    ("en_US",  "LOC_TRADITION_STRATAGEMS_COMBAT_DESCRIPTION",   "[B]+5 [icon:NAR_REW_COMBAT] [TIP:LOC_PEDIA_CONCEPTS_COMBAT_STRENGTH_TOOLTIP]Combat Strength[/TIP][/B] for Infantry and [TIP:LOC_PEDIA_CONCEPTS_CAVALRY_UNITS_TOOLTIP]Cavalry[/TIP] against other [TIP:LOC_PEDIA_CONCEPTS_LAND_UNITS_TOOLTIP]Land Units[/TIP] when you have at least [B]4 [icon:NAR_REW_GREATWORK] [TIP:LOC_PEDIA_CONCEPTS_GREAT_WORKS_TOOLTIP]Great Works[/TIP][/B] on display."),
    ("en_US",  "LOC_TRADITION_ICONOLATRY_DESCRIPTION",   "[TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlements[/TIP] with at least [B]1 [icon:NAR_REW_GREATWORK] [TIP:LOC_PEDIA_CONCEPTS_GREAT_WORKS_TOOLTIP]Great Work[/TIP][/B] gain [B]+10% [icon:YIELD_HAPPINESS] Happiness[/B] and [B][icon:YIELD_GOLD] Gold[/B]."),
    ("en_US",  "LOC_TRADITION_ICONOLATRY_II_DESCRIPTION",   "[TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlements[/TIP] with at least [B]1 [icon:NAR_REW_GREATWORK] [TIP:LOC_PEDIA_CONCEPTS_GREAT_WORKS_TOOLTIP]Great Work[/TIP][/B] gain [B]+10% [icon:YIELD_HAPPINESS] Happiness[/B] and [B][icon:YIELD_GOLD] Gold[/B]. [B]+3 [icon:YIELD_HAPPINESS] Happiness[/B] on Hidden Fortresses in [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlements[/TIP] with a [icon:NAR_REW_GREATWORK] Great Work Slotted."),
    ("en_US",  "LOC_TRADITION_ICONOLATRY_II_GREAT_WORKS_DESCRIPTION",   "[TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlements[/TIP] with at least [B]1 [icon:NAR_REW_GREATWORK] [TIP:LOC_PEDIA_CONCEPTS_GREAT_WORKS_TOOLTIP]Great Work[/TIP][/B] gain [B]+10% [icon:YIELD_HAPPINESS] Happiness[/B] and [B][icon:YIELD_GOLD] Gold[/B]."),
    -- Chola
    ("en_US", "LOC_CIVILIZATION_CHOLA_DESCRIPTION", "+1 [icon:TRADE_ROUTE] Trade Route from the Improve Trade Relations [icon:DiplomaticAction] Diplomatic Action. +3 [icon:YIELD_GOLD] Gold and +1 [icon:YIELD_DIPLOMACY] Influence for every active [icon:TRADE_ROUTE] Trade Route. Merchants gain +1 [icon:Action_Move] Movement."),
    ("en_US", "LOC_TRAIT_CHOLA_ABILITY_DESCRIPTION", "[BLIST][LI]+1 [icon:TRADE_ROUTE] Trade Route from the Improve Trade Relations [icon:DiplomaticAction] Diplomatic Action.[LI]+3 [icon:YIELD_GOLD] Gold and +1 [icon:YIELD_DIPLOMACY] Influence for every active [icon:TRADE_ROUTE] Trade Route.[LI]Merchants gain +1 [icon:Action_Move] Movement.[LI]+1 [icon:ECONOMIC_VP] GDP per turn for imported [icon:RADIAL_RESOURCES] Resources assigned to Cities.[LI]+30% [icon:YIELD_PRODUCTION] Production towards constructing Brihadeeswarar Temple.[/LIST]"),
    ("en_US", "LOC_TRAIT_CHOLA_ABILITY_MO_DESCRIPTION", "[BLIST][LI]+1 [icon:TRADE_ROUTE] Trade Route from the Improve Trade Relations [icon:DiplomaticAction] Diplomatic Action.[LI]+4 [icon:YIELD_GOLD] Gold and +2 [icon:YIELD_DIPLOMACY] Influence for every active [icon:TRADE_ROUTE] Trade Route.[LI]Merchants gain +1 [icon:Action_Move] Movement.[LI]+1 [icon:ECONOMIC_VP] GDP per turn for imported [icon:RADIAL_RESOURCES] Resources assigned to Cities.[/LIST]"),
    ("en_US", "LOC_BUILDING_ANJUVANNAM_DESCRIPTION", "Chola [TIP:LOC_PEDIA_CONCEPTS_UNIQUE_BUILDING_TOOLTIP]Unique Gold and Military Building[/TIP]. +6[icon:YIELD_GOLD] Gold. +1[icon:YIELD_GOLD] Gold Adjacency for Coastal Terrain, [TIP:LOC_PEDIA_CONCEPTS_NAVIGABLE_RIVER_TOOLTIP]Navigable Rivers[/TIP], and [TIP:LOC_PEDIA_CONCEPTS_WONDERS_TOOLTIP]Wonders[/TIP]. +25%[icon:YIELD_PRODUCTION] Production towards [TIP:LOC_PEDIA_CONCEPTS_NAVAL_UNITS_TOOLTIP]Naval Units[/TIP]. Must be placed adjacent to Coast."),
    ("en_US", "LOC_BUILDING_ANJUVANNAM_TOOLTIP", "Effect: +25%[icon:YIELD_PRODUCTION] towards [TIP:LOC_PEDIA_CONCEPTS_NAVAL_UNITS_TOOLTIP]Naval Units[/TIP].[N]Must be placed adjacent to Coast.[N]Chola [TIP:LOC_PEDIA_CONCEPTS_UNIQUE_BUILDING_TOOLTIP]Unique Military Building[/TIP]."),
    ("en_US", "LOC_MOD_ANJUVANNAM_SEA_UNIT_RATE_DESCRIPTION", "+25%[icon:YIELD_PRODUCTION] Production towards [TIP:LOC_PEDIA_CONCEPTS_NAVAL_UNITS_TOOLTIP]Naval Units[/TIP]."),
    ("en_US",  "LOC_UNIT_KALAM_BASE_DESCRIPTION",   "Chola Unique [TIP:LOC_PEDIA_CONCEPTS_NAVAL_UNITS_TOOLTIP]Heavy Naval Unit[/TIP].Has lower Combat Strength. +1 additional attack per turn if [icon:Action_Move] Movement allows. Has reduced base [icon:Action_Move] Movement."),
    ("en_US",  "LOC_UNIT_KALAM_DESCRIPTION",   "Tier 1 Chola Unique [TIP:LOC_PEDIA_CONCEPTS_NAVAL_UNITS_TOOLTIP]Heavy Naval Unit[/TIP].Has lower Combat Strength. +1 additional attack per turn if [icon:Action_Move] Movement allows. Has reduced base [icon:Action_Move] Movement."),
    ("en_US",  "LOC_UNIT_KALAM_2_DESCRIPTION",   "Tier 2 Chola Unique [TIP:LOC_PEDIA_CONCEPTS_NAVAL_UNITS_TOOLTIP]Heavy Naval Unit[/TIP].Has lower Combat Strength. +1 additional attack per turn if [icon:Action_Move] Movement allows. Has reduced base [icon:Action_Move] Movement."),
    ("en_US",  "LOC_UNIT_KALAM_3_DESCRIPTION",   "Tier 3 Chola Unique [TIP:LOC_PEDIA_CONCEPTS_NAVAL_UNITS_TOOLTIP]Heavy Naval Unit[/TIP].Has lower Combat Strength. +1 additional attack per turn if [icon:Action_Move] Movement allows. Has reduced base [icon:Action_Move] Movement."),
    -- Dai Veit
    ("en_US",  "LOC_TRADITION_DAI_VIET_SYNCRETISM_MODERN_DESCRIPTION",   "[B]+2 [icon:YIELD_CULTURE][/B] on [icon:CITY_RURAL] [TIP:LOC_PEDIA_CONCEPTS_IMPROVEMENT_TOOLTIP]Improvements[/TIP] and [icon:CITY_URBAN] [TIP:LOC_PEDIA_CONCEPTS_DISTRICT_TOOLTIP]Districts[/TIP] on [icon:CITY_UNIMPROVED] [TIP:LOC_PEDIA_CONCEPTS_VEGETATED_TERRAIN_TOOLTIP]Vegetation[/TIP] in [icon:CITY_UNIMPROVED] Tropical Terrain."),
	-- Hawai'i
    ("en_US", "LOC_TRADITION_KAPA_DESCRIPTION", "[B]+50% [icon:YIELD_PRODUCTION][/B] towards constructing [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Culture and Happiness Buildings[/TIP]."),
    ("en_US", "LOC_TRADITION_AHUPUA_A_I_DESCRIPTION", "[TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Culture Buildings[/TIP] gain a [B]+1 [icon:YIELD_FOOD] Food adjacency[/B] for Coast tiles."),
    ("en_US", "LOC_TRADITION_AHUPUA_A_II_DESCRIPTION", "[TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Culture Buildings[/TIP] gain a [B]+2 [icon:YIELD_FOOD] Food adjacency[/B] for Coast tiles."),  
   
    ("en_US", "LOC_CIVILIZATION_HAWAII_DESCRIPTION", "Can work Ocean Terrain. +1 [icon:YIELD_HAPPINESS] Happiness and +2 [icon:YIELD_CULTURE] Culture on all Marine Terrain."),
    ("en_US", "LOC_TRAIT_HAWAII_ABILITY_DESCRIPTION", "[BLIST][LI]Can work Ocean Terrain.[LI][B]+1 [icon:YIELD_HAPPINESS] Happiness[/B] and [B]+2 [icon:YIELD_FOOD] Food[/B] on all Marine Terrain.[LI]+30% [icon:YIELD_PRODUCTION] Production towards constructing Hale o Keawe.[/BLIST]"),
    ("en_US", "LOC_TRAIT_HAWAII_ABILITY_AQ_DESCRIPTION", "[BLIST][LI]Can work Ocean Terrain.[LI][B]+1 [icon:YIELD_Food] Food[/B] on all Marine Terrain.[/LIST]"),
    ("en_US", "LOC_TRAIT_HAWAII_ABILITY_MO_DESCRIPTION", "[BLIST][LI]Can work Ocean Terrain.[LI][B]+1 [icon:YIELD_HAPPINESS] Happiness[/B] and [B]+2 [icon:YIELD_Food] Food[/B] on all Marine Terrain.[/LIST]"),

    ("en_US", "LOC_TRADITION_HO_OKUPU_I_DESCRIPTION", "[B]+1 [icon:YIELD_CULTURE][/B] on Marine Terrain. [TIP:LOC_PEDIA_CONCEPTS_IMPROVEMENT_TOOLTIP]Improvements[/TIP], [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP], and [icon:CITY_URBAN] [TIP:LOC_PEDIA_CONCEPTS_DISTRICT_TOOLTIP]Districts[/TIP] do not get pillaged by Floods, Volcanic Eruptions, and Hurricanes."),
    ("en_US", "LOC_TRADITION_HO_OKUPU_II_DESCRIPTION", "[B]+2 [icon:YIELD_CULTURE][/B] on Marine Terrain. [TIP:LOC_PEDIA_CONCEPTS_IMPROVEMENT_TOOLTIP]Improvements[/TIP], [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP], and [icon:CITY_URBAN] [TIP:LOC_PEDIA_CONCEPTS_DISTRICT_TOOLTIP]Districts[/TIP] do not get pillaged by Floods, Volcanic Eruptions, and Hurricanes."),
    
    -- Iceland
    ("en_US",  "LOC_CIVILIZATION_ICELAND_DESCRIPTION",   "[B]+4 [icon:YIELD_CULTURE] Culture[/B] on [B][icon:NOTIFICATION_DISCOVER_NATURAL_WONDER] Natural Wonder[/B]. Gain [icon:YIELD_CULTURE] 500 Culture when you discover a [icon:NOTIFICATION_DISCOVER_NATURAL_WONDER] Natural Wonder in Distant Lands. Gain a [icon:NAR_REW_GREATWORK] Relic every time you study a [icon:RADIAL_CIVICS] Civic Mastery after completing the [icon:RADIAL_CIVICS] Landnámabók Civic. -50% [icon:YIELD_PRODUCTION] Production towards training [icon:UNIT_MISSIONARY] Missionaries, and [icon:UNIT_MISSIONARY] Missionaries cost 100% more [icon:YIELD_GOLD] Gold to purchase."),
    ("en_US",  "LOC_TRAIT_ICELAND_ABILITY_AQ_DESCRIPTION",   "[BLIST][LI][B]+1 [icon:Action_Showall] [TIP:LOC_PEDIA_CONCEPTS_SIGHT_TOOLTIP]Sight[/TIP][/B] for [B][TIP:LOC_PEDIA_CONCEPTS_NAVAL_UNITS_TOOLTIP]Naval Units[/TIP][/B].[LI][B]+2 [icon:YIELD_CULTURE] Culture[/B] on [B][icon:NOTIFICATION_DISCOVER_NATURAL_WONDER] Natural Wonder[/B][LI]Gain [B]250 [icon:YIELD_CULTURE] Culture[/B] when you discover a [icon:NOTIFICATION_DISCOVER_NATURAL_WONDER] [B]Natural Wonder[/B] (On Standard Speed).[/BLIST]"),
    ("en_US",  "LOC_TRAIT_ICELAND_ABILITY_DESCRIPTION",   "[BLIST][LI][B]+1 [icon:Action_Showall] [TIP:LOC_PEDIA_CONCEPTS_SIGHT_TOOLTIP]Sight[/TIP][/B] for [B][TIP:LOC_PEDIA_CONCEPTS_NAVAL_UNITS_TOOLTIP]Naval Units[/TIP][/B].[LI][B]+3 [icon:YIELD_CULTURE] Culture[/B] on [B][icon:NOTIFICATION_DISCOVER_NATURAL_WONDER] Natural Wonder[/B][LI]Gain [B]500 [icon:YIELD_CULTURE] Culture[/B] when you discover a [icon:NOTIFICATION_DISCOVER_NATURAL_WONDER] [B]Natural Wonder[/B] in [B]Distant Lands[/B] (On Standard Speed). [LI]Gain a [B][icon:NAR_REW_GREATWORK] Relic[/B] every time you study a [B][icon:RADIAL_CIVICS] Civic Mastery[/B].[LI][B]-50% [icon:YIELD_PRODUCTION] Production[/B] towards training [B][icon:UNIT_MISSIONARY] Missionaries[/B], and [icon:UNIT_MISSIONARY] Missionaries cost [B]100% more [icon:YIELD_GOLD] Gold[/B] to purchase.[LI][B]+30%[icon:YIELD_PRODUCTION] Production [/B]towards constructing [B]Reykjaholt[/B].[/LIST]"),
    ("en_US", "LOC_TRADITION_DROTTKVAETT_I_DESCRIPTION", "Coastal Raiding grants +50% [icon:YIELD_CULTURE] Culture."),
    ("en_US", "LOC_TRADITION_DROTTKVAETT_II_DESCRIPTION", "Coastal Raiding grants +100% [icon:YIELD_CULTURE] Culture."),
    ("en_US",  "MBM_LOC_TRADITION_REIDI_GUDANNA_I_NAME",   "Reiði Guðanna I"),
    ("en_US",  "MBM_LOC_TRADITION_REIDI_GUDANNA_I_DESCRIPTION",   "All [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP] gain a [B]+1 [icon:YIELD_CULTURE][/B] Cultural Adjacency from Volcanoes and [icon:NOTIFICATION_DISCOVER_NATURAL_WONDER] [TIP:LOC_PEDIA_CONCEPTS_NATURAL_WONDER_TOOLTIP]Natural Wonders[/TIP]. ( [icon:NOTIFICATION_DISCOVER_NATURAL_WONDER] Natural Wonder Volcanoes do not count twice)."),
    -- Inca
    ("en_US",  "LOC_CIVILIZATION_INCA_DESCRIPTION",   "Can work Mountain Terrain. +3 [icon:YIELD_FOOD] Food and +1 [icon:YIELD_PRODUCTION] Production on Mountain Terrain. Can generate [TIP:LOC_PEDIA_CONCEPTS_HOMELANDS_TOOLTIP]Homelands[/TIP] [icon:UNIT_TREASURE_FLEET] [TIP:LOC_PEDIA_CONCEPTS_TREASURE_CONVOY_TOOLTIP]Treasure Convoys[/TIP] in [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] with 3 Worked Mountains after completing the Qhapaq Ñan [icon:CIVICS] [TIP:LOC_PEDIA_CONCEPTS_CIVIC_TOOLTIP]Civic[/TIP]."),
    ("en_US",  "LOC_TRAIT_INCA_ABILITY_DESCRIPTION",   "[BLIST][LI]Can work Mountain Terrain.[LI][B]+3 [icon:YIELD_FOOD] Food[/B] and [B]+1 [icon:YIELD_PRODUCTION] Production[/B] on Mountain Terrain.[LI]Can generate [TIP:LOC_PEDIA_CONCEPTS_HOMELANDS_TOOLTIP]Homelands[/TIP] [icon:UNIT_TREASURE_FLEET] [TIP:LOC_PEDIA_CONCEPTS_TREASURE_CONVOY_TOOLTIP]Treasure Convoys[/TIP] in [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] with 3 Worked Mountains after completing the Qhapaq Ñan [icon:CIVICS] [TIP:LOC_PEDIA_CONCEPTS_CIVIC_TOOLTIP]Civic[/TIP].[LI][B]+30% [icon:YIELD_PRODUCTION] Production[/B] towards constructing Machu Pikchu.[/BLIST]"),
    ("en_US",  "LOC_TRAIT_INCA_ABILITY_AQ_DESCRIPTION",   "[BLIST][LI]Can work Mountain Terrain.[LI][B]+2 [icon:YIELD_FOOD] Food[/B] and [B]+1 [icon:YIELD_PRODUCTION] Production[/B] on Mountain Terrain.[/LIST]"),
    
    ("en_US",  "LOC_IMPROVEMENT_TERRACE_FARM_DESCRIPTION",   "Incan [TIP:LOC_PEDIA_CONCEPTS_UNIQUE_IMPROVEMENT_TOOLTIP]Unique Improvement[/TIP]. +4 [icon:YIELD_FOOD] Food. +1 [icon:YIELD_GOLD] Gold to all adjacent [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP]. Must be placed on Mountain Terrain or [TIP:LOC_PEDIA_CONCEPTS_ROUGH_TERRAIN_TOOLTIP]Rough Terrain[/TIP] without a River or Feature."),
    ("en_US",  "LOC_IMPROVEMENT_TERRACE_FARM_TOOLTIP",   "+1 [icon:YIELD_GOLD] to all adjacent [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP].[n][TIP:LOC_PEDIA_CONCEPTS_UNIQUE_IMPROVEMENT_TOOLTIP]Unique Improvement[/TIP] must be placed on Mountain Terrain or [TIP:LOC_PEDIA_CONCEPTS_ROUGH_TERRAIN_TOOLTIP]Rough Terrain[/TIP] without a River or Feature.[n]Incan [TIP:LOC_PEDIA_CONCEPTS_UNIQUE_IMPROVEMENT_TOOLTIP]Unique Improvement[/TIP]."),
    ("en_US",  "LOC_TRADITION_QULLQA_I_DESCRIPTION",   "[icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] gain [B]+2 [icon:YIELD_FOOD] Food[/B] for each active [icon:TRADE_ROUTE] [TIP:LOC_PEDIA_CONCEPTS_TRADE_ROUTE_TOOLTIP]Trade Route[/TIP] you started."),
    ("en_US",  "LOC_TRADITION_QULLQA_II_DESCRIPTION",   "[icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] gain [B]+2 [icon:YIELD_FOOD] Food[/B] and [B]+1 [icon:YIELD_PRODUCTION] Production[/B] for each active [icon:TRADE_ROUTE] [TIP:LOC_PEDIA_CONCEPTS_TRADE_ROUTE_TOOLTIP]Trade Route[/TIP] you started."),
    ("en_US",  "LOC_TRADITION_TIRAKUNA_I_DESCRIPTION",   "Food and Gold [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP] receive a [B]+1 adjacency[/B] for Mountains. [icon:CITY_UNIMPROVED] [TIP:LOC_PEDIA_CONCEPTS_ROUGH_TERRAIN_TOOLTIP]Rough Terrain[/TIP] does not end Unit [icon:Action_Move] Movement."),
    ("en_US",  "LOC_TRADITION_TIRAKUNA_II_DESCRIPTION",   "Food and Gold [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP] receive a [B]+2 adjacency[/B] for Mountains. [icon:CITY_UNIMPROVED] [TIP:LOC_PEDIA_CONCEPTS_ROUGH_TERRAIN_TOOLTIP]Rough Terrain[/TIP] does not end Unit [icon:Action_Move] Movement."),
    ("en_US",  "LOC_TRADITION_INCA_SYNCRETISM_ANTIQUITY_DESCRIPTION",   "[B]+2 [icon:YIELD_FOOD] Food[/B] on Mountain Terrain."),
    ("en_US",  "LOC_TRADITION_INCA_SYNCRETISM_MODERN_DESCRIPTION",   "[B]+2 [icon:YIELD_FOOD] Food[/B] and [B]+2 [icon:YIELD_PRODUCTION] Production[/B] on Mountain Terrain."),
    -- Majapahit
    ("en_US",  "LOC_TRADITION_AWISAN_DALEM_I_DESCRIPTION",   "+1 [icon:YIELD_PRODUCTION] on [icon:CITY_UNIMPROVED] Marine Terrain in [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP]."),
    -- Ming
    ("en_US",  "LOC_CIVILIZATION_MING_DESCRIPTION",   "+50% [icon:YIELD_SCIENCE] Science in the [icon:NOTIFICATION_SELECT_CAPITAL] [TIP:LOC_PEDIA_CONCEPTS_CAPITAL_TOOLTIP]Capital[/TIP]. -5 [icon:YIELD_SCIENCE] Science per turn for each [icon:SOCIAL_POLICY] [TIP:LOC_PEDIA_CONCEPTS_SOCIAL_POLICY_TOOLTIP]Social Policy[/TIP], but not [icon:TRADITION] [TIP:LOC_PEDIA_CONCEPTS_TRADITION_TOOLTIP]Tradition[/TIP], slotted in the [icon:GOVERNMENT] [TIP:LOC_PEDIA_CONCEPTS_GOVERNMENT_TOOLTIP]Government[/TIP]."),
    ("en_US",  "LOC_TRAIT_MING_ABILITY_DESCRIPTION",   "[BLIST][LI][B]+50% [icon:YIELD_SCIENCE] Science[/B] in the [icon:NOTIFICATION_SELECT_CAPITAL] [TIP:LOC_PEDIA_CONCEPTS_CAPITAL_TOOLTIP]Capital[/TIP].[LI][B]-5 [icon:YIELD_SCIENCE] Science[/B] per turn for each [icon:SOCIAL_POLICY] [TIP:LOC_PEDIA_CONCEPTS_SOCIAL_POLICY_TOOLTIP]Social Policy[/TIP], but not [icon:TRADITION] [TIP:LOC_PEDIA_CONCEPTS_TRADITION_TOOLTIP]Tradition[/TIP], slotted in the [icon:GOVERNMENT] [TIP:LOC_PEDIA_CONCEPTS_GOVERNMENT_TOOLTIP]Government[/TIP].[LI][B]+1 [icon:NAR_REW_TRADITION_SLOT] Tradition Slot[/B].[LI][B]+30% [icon:YIELD_PRODUCTION] Production[/B] towards constructing the Forbidden City.[/BLIST]"),
    ("en_US",  "LOC_TRAIT_MING_ABILITY_MO_DESCRIPTION",   "[BLIST][LI][B]+50% [icon:YIELD_SCIENCE] Science[/B] in the [icon:NOTIFICATION_SELECT_CAPITAL] [TIP:LOC_PEDIA_CONCEPTS_CAPITAL_TOOLTIP]Capital[/TIP].[LI][B]-8 [icon:YIELD_SCIENCE] Science[/B] per turn for each [icon:SOCIAL_POLICY] [TIP:LOC_PEDIA_CONCEPTS_SOCIAL_POLICY_TOOLTIP]Social Policy[/TIP], but not [icon:TRADITION] [TIP:LOC_PEDIA_CONCEPTS_TRADITION_TOOLTIP]Tradition[/TIP], slotted in the [icon:GOVERNMENT] [TIP:LOC_PEDIA_CONCEPTS_GOVERNMENT_TOOLTIP]Government[/TIP].[LI][B]+1 [icon:NAR_REW_TRADITION_SLOT] Tradition Slot[/B].[/BLIST]"),
    ("en_US", "LOC_IMPROVEMENT_MING_GREAT_WALL_DESCRIPTION", "Ming [TIP:LOC_PEDIA_CONCEPTS_UNIQUE_IMPROVEMENT_TOOLTIP]Unique Improvement[/TIP]. +5 [icon:YIELD_CULTURE] Culture. +1 [icon:YIELD_GOLD] Gold Adjacency for Fortification Constructibles. Counts as a Fortification, granting +6 [icon:NAR_REW_COMBAT] Combat Strength for Units defending on the tile. A Road is also placed with each Great Wall Segment. Can only be built in a line and cannot branch or fork. Has reduced cost scaling compared to other Unique Improvements."),
    ("en_US", "LOC_IMPROVEMENT_MING_GREAT_WALL_TOOLTIP", "Effect: Counts as a Fortification, granting +6 [icon:NAR_REW_COMBAT] Combat Strength for Units defending on the tile.[N]A Road is also placed with each Great Wall Segment. Can only be built in a line and cannot branch or fork.[N]Ming Unique Improvement."),
    ("en_US", "LOC_ABILITY_XUNLEICHONG_DESCRIPTION", "Has a [icon:Action_Ranged] Ranged attack."),
    ("en_US", "LOC_UNIT_XUNLEICHONG_BASE_DESCRIPTION", "Ming Unique Infantry Unit. Has a [icon:Action_Ranged] Ranged attack with reduced Ranged Combat Strength."),
    ("en_US", "LOC_UNIT_XUNLEICHONG_DESCRIPTION", "Tier 1 Ming Unique Infantry Unit. Has a [icon:Action_Ranged] Ranged attack with reduced Ranged Combat Strength."),
    ("en_US", "LOC_UNIT_XUNLEICHONG_2_DESCRIPTION", "Tier 2 Ming Unique Infantry Unit. Has a [icon:Action_Ranged] Ranged attack with reduced Ranged Combat Strength."),
    ("en_US", "LOC_UNIT_XUNLEICHONG_3_DESCRIPTION", "Tier 3 Ming Unique Infantry Unit. Has a [icon:Action_Ranged] Ranged attack with reduced Ranged Combat Strength."),
    ("en_US",  "LOC_ABILITY_XUNLEICHONG_BONUS_DESCRIPTION",   "+1 [icon:Action_Ranged] [TIP:LOC_PEDIA_CONCEPTS_COMBAT_STRENGTH_TOOLTIP]Combat Strength[/TIP] to [TIP:LOC_PEDIA_CONCEPTS_RANGED_UNITS_TOOLTIP]Ranged Units[/TIP] adjacent to the Xunleichong."),
    
    --Mongolia
    ("en_US",  "LOC_TRAIT_MONGOLIA_ABILITY_AQ_DESCRIPTION",   "[BLIST][LI]When you capture an opposing [TIP:LOC_PEDIA_CONCEPTS_SETTLEMENT_TOOLTIP]Settlement[/TIP] gain the strongest [TIP:LOC_PEDIA_CONCEPTS_CAVALRY_UNITS_TOOLTIP]Cavalry Unit[/TIP] you can currently train.[LI]Chariots are unlocked with Agriculture.[/LIST]"),
    ("en_US",  "LOC_TRADITION_BAGHATUR_II_DESCRIPTION",   "[B]+3 [icon:NAR_REW_COMBAT][/B] [TIP:LOC_PEDIA_CONCEPTS_COMBAT_STRENGTH_TOOLTIP]Combat Strength[/TIP] and [B]+1 [icon:Action_Move] Movement[/B] for [TIP:LOC_PEDIA_CONCEPTS_CAVALRY_UNITS_TOOLTIP]Cavalry Units[/TIP]."),
    -- Normans
    ("en_US",  "LOC_TRADITION_SERVITIUM_DEBITUM_DESCRIPTION",   "[B]+1 [icon:NAR_REW_COMBAT][/B] [TIP:LOC_PEDIA_CONCEPTS_COMBAT_STRENGTH_TOOLTIP]Combat Strength[/TIP] for [TIP:LOC_PEDIA_CONCEPTS_CAVALRY_UNITS_TOOLTIP]Cavalry Units[/TIP] for every [icon:TRADITION] [TIP:LOC_PEDIA_CONCEPTS_TRADITION_TOOLTIP]Tradition[/TIP] slotted in the [icon:GOVERNMENT] [TIP:LOC_PEDIA_CONCEPTS_GOVERNMENT_TOOLTIP]Government[/TIP], up to [B]+4[/B]. [B]-2 [icon:YIELD_GOLD][/B] [TIP:LOC_PEDIA_CONCEPTS_MAINTENANCE_TOOLTIP]Maintenance[/TIP] for Cavalry Units."),
    -- Pirates
    ("en_US",  "LOC_TRAIT_PIRATE_REPUBLIC_ABILITY_AQ_DESCRIPTION",   "[BLIST][LI][B]Naval Units[/B] can move into other [B]Civilization's[/B] borders without being at [icon:WAR] [B]War[/B] or having [B]Open Borders[/B].[LI][icon:UNIT_SETTLER] [B]Settlers[/B] cannot be trained or purchased, but you can capture other Civilizations' [icon:UNIT_SETTLER] [B]Settlers[/B]. Gain a free [icon:UNIT_SETTLER] [B]Settler[/B] upon completing the [icon:RADIAL_TECH] Sailing, Currency and Navigation Technologies and the [icon:RADIAL_CIVICS] Pirate Origins, Pirate Foundation, Discipline, Organized Military, Skilled Trades and Commerce Civics.[LI]+5 [icon:ECONOMIC_VP] [TIP:LOC_PEDIA_CONCEPTS_GDP_TOOLTIP]GDP[/TIP] from your [TIP:LOC_PEDIA_CONCEPTS_NAVAL_UNITS_TOOLTIP]Naval Units[/TIP] defeating other [B]Units[/B].[/BLIST]"),
    ("en_US",  "LOC_TRADITION_BLACK_FLAG_I_DESCRIPTION",   "[B]+50 [icon:YIELD_GOLD][/B] (Scales with Game Speed) from [icon:Action_Pillage] Plundering [icon:TRADE_ROUTE] [TIP:LOC_PEDIA_CONCEPTS_TRADE_ROUTE_TOOLTIP]Trade Routes[/TIP]. +50% Yields and [icon:Action_Heal] Healing from [icon:Action_Pillage] Coastal Raiding with [TIP:LOC_PEDIA_CONCEPTS_NAVAL_UNITS_TOOLTIP]Naval Units[/TIP]. Pillaging with [TIP:LOC_PEDIA_CONCEPTS_NAVAL_UNITS_TOOLTIP]Naval Units[/TIP] grants [icon:YIELD_GOLD] equal to 50% of [icon:Action_Pillage] Pillage Yields and [icon:Action_Heal] Healing."),
    ("en_US",  "LOC_TRADITION_BLACK_FLAG_II_DESCRIPTION",   "[B]+100 [icon:YIELD_GOLD][/B] (Scales with Game Speed) from [icon:Action_Pillage] Plundering [icon:TRADE_ROUTE] [TIP:LOC_PEDIA_CONCEPTS_TRADE_ROUTE_TOOLTIP]Trade Routes[/TIP]. +100% Yields and [icon:Action_Heal] Healing from [icon:Action_Pillage] Coastal Raiding with [TIP:LOC_PEDIA_CONCEPTS_NAVAL_UNITS_TOOLTIP]Naval Units[/TIP]. Pillaging with [TIP:LOC_PEDIA_CONCEPTS_NAVAL_UNITS_TOOLTIP]Naval Units[/TIP] grants [icon:YIELD_GOLD] equal to 100% of [icon:Action_Pillage] Pillage Yields and [icon:Action_Heal] Healing. [icon:UNIT_FLEET_COMMANDER] [TIP:LOC_PEDIA_CONCEPTS_COMMANDER_TOOLTIP]Fleet Commanders[/TIP] and Naval Units gain [TIP:LOC_PEDIA_CONCEPTS_STEALTH_TOOLTIP]Stealth[/TIP] on Atolls."),
    -- Sengoku
    ("en_US", "LOC_CIVILIZATION_SENGOKU_DESCRIPTION", "+2 [icon:YIELD_CULTURE] Culture and +2 [icon:YIELD_SCIENCE] Science per turn for each Army Commander Promotion. Culture Buildings lose Mountain adjacency and Science Buildings lose Resource adjacency."),
    ("en_US", "LOC_TRAIT_SENGOKU_ABILITY_AQ_DESCRIPTION", "[BLIST][LI][B]+1[/B] [icon:YIELD_CULTURE] Culture and [B]+1[/B] [icon:YIELD_SCIENCE] Science per turn for each [icon:UNIT_ARMY_COMMANDER] Army [TIP:LOC_PEDIA_CONCEPTS_COMMANDER_TOOLTIP]Commander[/TIP] Promotion.[LI]Culture Buildings lose Mountain adjacency.[LI][B][icon:YIELD_CULTURE] Culture[/B] [B][icon:CITY_BUILDING_LIST] [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP][/B] no longer receive an Adjacency with [B][icon:CITY_UNIMPROVED] Mountain Terrain[/B].[LI][B][icon:YIELD_SCIENCE] Science[/B] [B][icon:CITY_BUILDING_LIST] [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP][/B] no longer receive an Adjacency with [B][icon:RADIAL_RESOURCES] [TIP:LOC_PEDIA_CONCEPTS_RESOURCES_TOOLTIP]Resources[/TIP][/B].[/LIST]"),
    ("en_US", "LOC_TRAIT_SENGOKU_ABILITY_EX_DESCRIPTION", "[BLIST][LI][B]+2[/B] [icon:YIELD_CULTURE] Culture and [B]+2[/B] [icon:YIELD_SCIENCE] Science per turn for each [icon:UNIT_ARMY_COMMANDER] Army [TIP:LOC_PEDIA_CONCEPTS_COMMANDER_TOOLTIP]Commander[/TIP] Promotion.[LI][B][icon:YIELD_CULTURE] Culture[/B] [B][icon:CITY_BUILDING_LIST] [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP][/B] no longer receive an Adjacency with [B][icon:CITY_UNIMPROVED] Mountain Terrain[/B].[LI][B][icon:YIELD_SCIENCE] Science[/B] [B][icon:CITY_BUILDING_LIST] [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP][/B] no longer receive an Adjacency with [B][icon:RADIAL_RESOURCES] [TIP:LOC_PEDIA_CONCEPTS_RESOURCES_TOOLTIP]Resources[/TIP][/B].[LI]+30% [icon:YIELD_PRODUCTION] Production towards constructing Himeji Castle.[/LIST]"),
    ("en_US", "LOC_TRAIT_SENGOKU_ABILITY_MO_DESCRIPTION", "[BLIST][LI][B]+3[/B] [icon:YIELD_CULTURE] Culture, [B]+3[/B] [icon:YIELD_SCIENCE] Science, and [B]+1[/B] [icon:YIELD_DIPLOMACY] Influence per turn for each [icon:UNIT_ARMY_COMMANDER] Army [TIP:LOC_PEDIA_CONCEPTS_COMMANDER_TOOLTIP]Commander[/TIP] Promotion.[LI][B][icon:YIELD_CULTURE] Culture[/B] [B][icon:CITY_BUILDING_LIST] [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP][/B] no longer receive an Adjacency with [B][icon:CITY_UNIMPROVED] Mountain Terrain[/B].[LI][B][icon:YIELD_SCIENCE] Science[/B] [B][icon:CITY_BUILDING_LIST] [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP][/B] no longer receive an Adjacency with [B][icon:RADIAL_RESOURCES] [TIP:LOC_PEDIA_CONCEPTS_RESOURCES_TOOLTIP]Resources[/TIP][/B].[/LIST]"),
    ("en_US", "LOC_TRADITION_DAIMYO_DESCRIPTION", "Infantry Units fight as though they were at full [icon:NAR_REW_COMBAT] Combat Strength even when damaged."),
    ("en_US", "LOC_TRADITION_KABUNAKAMA_DESCRIPTION", "+1 [icon:YIELD_PRODUCTION] Production in all Settlements for each active Trade Route. +3 [icon:NAR_REW_COMBAT] Combat Strength to Infantry Units. -25 [icon:YIELD_GOLD] Gold in Cities without a Garrisoned unit."),
    ("en_US", "LOC_TRADITION_KABUNAKAMA_II_DESCRIPTION", "+2 [icon:YIELD_PRODUCTION] Production in all Settlements for each active Trade Route. +3 [icon:NAR_REW_COMBAT] Combat Strength to Infantry Units. -25 [icon:YIELD_GOLD] Gold in Cities without a Garrisoned unit."),
    ("en_US", "LOC_MBM_UNLOCK_LEVEL_8_COMMANDER_DESCRIPTION", "Have a Level 8 Commander."),
    ("en_US", "LOC_MBM_UNLOCK_LEVEL_8_COMMANDER_SENGOKU_TOOLTIP", "Unlock Sengoku by having a Level 8 Commander during Antiquity."),
    ("en_US",  "LOC_TRADITION_GEKOKUJO_I_DESCRIPTION",   "[B]+25% [icon:UNIT_ARMY_COMMANDER] [TIP:LOC_PEDIA_CONCEPTS_COMMANDER_TOOLTIP]Army Commander[/TIP][/B] [TIP:LOC_PEDIA_CONCEPTS_COMMANDER_EXPERIENCE_TOOLTIP]XP[/TIP]. But all [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP] have an additional [icon:YIELD_HAPPINESS] [TIP:LOC_PEDIA_CONCEPTS_MAINTENANCE_TOOLTIP]Maintenance[/TIP]."),
    ("en_US",  "LOC_TRADITION_GEKOKUJO_DESCRIPTION",   "[B]+50% [icon:UNIT_ARMY_COMMANDER] [TIP:LOC_PEDIA_CONCEPTS_COMMANDER_TOOLTIP]Army Commander[/TIP][/B] [TIP:LOC_PEDIA_CONCEPTS_COMMANDER_EXPERIENCE_TOOLTIP]XP[/TIP]. But all [TIP:LOC_PEDIA_CONCEPTS_BUILDINGS_TOOLTIP]Buildings[/TIP] have an additional [icon:YIELD_HAPPINESS] [TIP:LOC_PEDIA_CONCEPTS_MAINTENANCE_TOOLTIP]Maintenance[/TIP]."),
    -- Shawnee
    ("en_US",  "LOC_TRADITION_TAKESIYAKE_YEPEPOKI_I_NAME",   "Takesiyake Yepepoki I"),
    ("en_US",  "LOC_TRADITION_TAKESIYAKE_YEPEPOKI_I_DESCRIPTION",   "[B]+1 [icon:YIELD_PRODUCTION][/B] on [icon:CITY_RURAL] [TIP:LOC_PEDIA_CONCEPTS_IMPROVEMENT_TOOLTIP]Improvements[/TIP] on [icon:CITY_UNIMPROVED] Tundra, Desert, and Plains Terrain in [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP]. These numbers are doubled if the tile is also [TIP:LOC_PEDIA_CONCEPTS_NAVIGABLE_RIVER_TOOLTIP]Navigable River[/TIP] Terrain."),
    ("en_US",  "LOC_TRADITION_SHAWNEE_SYNCRETISM_ANTIQUITY_DESCRIPTION",   "[B]+1 [icon:YIELD_DIPLOMACY][/B] in [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] adjacent to [TIP:LOC_PEDIA_CONCEPTS_NAVIGABLE_RIVER_TOOLTIP]Navigable Rivers[/TIP]. [B]+2 [icon:YIELD_GOLD][/B] in [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] per [icon:CITYSTATE] [TIP:LOC_PEDIA_CONCEPTS_CITY_STATE_TOOLTIP]City-State[/TIP] you are [TIP:LOC_PEDIA_CONCEPTS_SUZERAIN_TOOLTIP]Suzerain[/TIP] of."),
    ("en_US",  "LOC_TRADITION_SHAWNEE_SYNCRETISM_MODERN_DESCRIPTION",   "[B]+2 [icon:YIELD_DIPLOMACY][/B] in [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] adjacent to [TIP:LOC_PEDIA_CONCEPTS_NAVIGABLE_RIVER_TOOLTIP]Navigable Rivers[/TIP]. [B]+4 [icon:YIELD_GOLD][/B] in [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] per [icon:CITYSTATE] [TIP:LOC_PEDIA_CONCEPTS_CITY_STATE_TOOLTIP]City-State[/TIP] you are [TIP:LOC_PEDIA_CONCEPTS_SUZERAIN_TOOLTIP]Suzerain[/TIP] of."),
    ("en_US", "LOC_TRADITION_BREAD_DANCE_I_DESCRIPTION", "+1 [icon:YIELD_CULTURE] Culture on Farms and +1 [icon:YIELD_FOOD] Food on Fishing Boats in Farming and Fishing Towns."),
    ("en_US", "LOC_TRADITION_BREAD_DANCE_II_DESCRIPTION", "+2 [icon:YIELD_CULTURE] Culture on Farms and +2 [icon:YIELD_FOOD] Food on Fishing Boats in Farming and Fishing Towns."),
    -- Songhai
    ("en_US",  "LOC_TRADITION_SONGHAI_SYNCRETISM_ANTIQUITY_DESCRIPTION",   "[B]+1 [icon:YIELD_GOLD][/B] on [icon:CITY_RURAL] [TIP:LOC_PEDIA_CONCEPTS_IMPROVEMENT_TOOLTIP]Improvements[/TIP] on [icon:CITY_UNIMPROVED] Desert and Plains Terrain, doubled on [icon:CITY_RURAL] [TIP:LOC_PEDIA_CONCEPTS_UNIQUE_IMPROVEMENT_TOOLTIP]Unique Improvements[/TIP]."),
    ("en_US",  "LOC_TRADITION_SONGHAI_SYNCRETISM_MODERN_DESCRIPTION",   "[B]+2 [icon:YIELD_GOLD][/B] on [icon:CITY_RURAL] [TIP:LOC_PEDIA_CONCEPTS_IMPROVEMENT_TOOLTIP]Improvements[/TIP] on [icon:CITY_UNIMPROVED] Desert and Plains Terrain, doubled on [icon:CITY_RURAL] [TIP:LOC_PEDIA_CONCEPTS_UNIQUE_IMPROVEMENT_TOOLTIP]Unique Improvements[/TIP]."),

    -- Wonders
    -- Thanh Hue
    ('en_US',  'LOC_WONDER_THANH_HUE_DESCRIPTION',   '+4 [icon:YIELD_CULTURE] Culture. +1 [icon:SPECIALIST] [TIP:LOC_PEDIA_CONCEPTS_SPECIALIST_LIMIT_TOOLTIP]Specialist Limit[/TIP] and [icon:SPECIALIST] [TIP:LOC_PEDIA_CONCEPTS_SPECIALIST_TOOLTIP]Specialists[/TIP] recieve +1 [icon:YIELD_CULTURE] Culture in [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] with 3 [icon:Action_Fortify] Fortification Constructibles. Acts as a [icon:CITY_FORTIFIED] [TIP:LOC_PEDIA_CONCEPTS_FORTIFIED_DISTRICTS_TOOLTIP]Fortified District[/TIP] that must be conquered. Ageless. Must be built adjacent to Medieval Walls, in a [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]City[/TIP] with 3 Medieval Walls.'),
    ('en_US',  'LOC_WONDER_THANH_HUE_TOOLTIP',   '+1 [icon:SPECIALIST] [TIP:LOC_PEDIA_CONCEPTS_SPECIALIST_LIMIT_TOOLTIP]Specialist Limit[/TIP] and [icon:SPECIALIST] [TIP:LOC_PEDIA_CONCEPTS_SPECIALIST_TOOLTIP]Specialists[/TIP] recieve +1 [icon:YIELD_CULTURE] Culture in [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] with 3 [icon:Action_Fortify] Fortification Constructibles. Acts as a [icon:CITY_FORTIFIED] [TIP:LOC_PEDIA_CONCEPTS_FORTIFIED_DISTRICTS_TOOLTIP]Fortified District[/TIP] that must be conquered.[N]Must be built adjacent to Medieval Walls, in a [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]City[/TIP] with 3 Medieval Walls.'),

-- Government
    ("en_US", "LOC_TRADITION_MAHAKRUNG_DESCRIPTION", "[B]+10 [icon:YIELD_CULTURE] Culture, [icon:YIELD_PRODUCTION] Production, and [icon:YIELD_GOLD] Gold[/B] in your [icon:NOTIFICATION_SELECT_CAPITAL] [TIP:LOC_PEDIA_CONCEPTS_CAPITAL_TOOLTIP]Capital[/TIP], or +15 if Joyous, or +20 if Ecstatic."),
    ("en_US", "LOC_GOVERNMENT_PLUTOCRACY_PASSIVE_DESCRIPTION", "[B]+30% [icon:YIELD_PRODUCTION] Production[/B] towards Overbuilding."),
    ("en_US", "LOC_GOLDEN_AGE_PLUTOCRACY_2_DESCRIPTION", "Create a [icon:UNIT_MIGRANT] Migrant in the [icon:NOTIFICATION_SELECT_CAPITAL] [TIP:LOC_PEDIA_CONCEPTS_CAPITAL_TOOLTIP]Capital[/TIP]."),
    ("en_US", "LOC_TRADITION_TEQUITL_DESCRIPTION", "+10 [TIP:LOC_PEDIA_CONCEPTS_TRADE_RANGE_TOOLTIP]Trade Range[/TIP]. [B]+1 [icon:YIELD_SCIENCE] Science[/B] for every imported [icon:RADIAL_RESOURCES] [TIP:LOC_PEDIA_CONCEPTS_RESOURCES_TOOLTIP]Resource[/TIP]."),
    ("en_US", "LOC_GOVERNMENT_THEOCRACY_PASSIVE_DESCRIPTION", "[B]+30% [icon:YIELD_PRODUCTION] Production[/B] and [B][icon:YIELD_GOLD] Gold[/B] towards constructing or purchasing Temples and Missionaries."),
    ("en_US", "LOC_GOLDEN_AGE_THEOCRACY_2_DESCRIPTION", "Missionaries gain +1 [icon:Action_Move] Movement and ignore movement penalties from Rough and Vegetated terrain for {1_numTurns} Turn(s)."),
    ("en_US", "LOC_TRADITION_DARGAH_DESCRIPTION", "[B]+4 [icon:YIELD_FOOD] Food[/B] and [B][icon:YIELD_HAPPINESS] Happiness[/B] in [icon:YIELD_TOWNS] [TIP:LOC_PEDIA_CONCEPTS_TOWN_TOOLTIP]Towns[/TIP] following your [icon:NAR_REW_RELIGION] [TIP:LOC_PEDIA_CONCEPTS_RELIGION_TOOLTIP]Religion[/TIP]."),
    ("en_US", "LOC_TRADITION_VINAYA_DESCRIPTION", "[B]+5 [icon:YIELD_GOLD] Gold[/B] and [B]+2 [icon:YIELD_DIPLOMACY] Influence[/B] in [icon:YIELD_CITIES] [TIP:LOC_PEDIA_CONCEPTS_CITIES_TOOLTIP]Cities[/TIP] following your [icon:NAR_REW_RELIGION] [TIP:LOC_PEDIA_CONCEPTS_RELIGION_TOOLTIP]Religion[/TIP]."),

-- Policy Card balance
    ("en_US", "LOC_TRADITION_COMMUNE_DESCRIPTION", "[B]+30% [icon:YIELD_PRODUCTION][/B] towards [TIP:LOC_PEDIA_CONCEPTS_OVERBUILDABLE_TOOLTIP]Overbuilding[/TIP]. [B]+3 [icon:NAR_REW_COMBAT][/B] [TIP:LOC_PEDIA_CONCEPTS_COMBAT_STRENGTH_TOOLTIP]Combat Strength[/TIP] for [icon:CITY_FORTIFIED] [TIP:LOC_PEDIA_CONCEPTS_FORTIFIED_DISTRICTS_TOOLTIP]Fortified Districts[/TIP]."),
    ("en_US", "LOC_TRADITION_TRADE_WINDS_DESCRIPTION", "[B]+1 [icon:YIELD_GOLD][/B] and [icon:YIELD_HAPPINESS] for every imported [icon:RADIAL_RESOURCES] [TIP:LOC_PEDIA_CONCEPTS_RESOURCES_TOOLTIP]Resource[/TIP]. [B]+5[/B] [TIP:LOC_PEDIA_CONCEPTS_TRADE_RANGE_TOOLTIP]Trade Range[/TIP]."),
    ("en_US", "LOC_TRADITION_REGULARS_DESCRIPTION", "[B]+30% [icon:YIELD_PRODUCTION][/B] towards training [TIP:LOC_PEDIA_CONCEPTS_INFANTRY_UNITS_TOOLTIP]Infantry[/TIP] and [TIP:LOC_PEDIA_CONCEPTS_RANGED_UNITS_TOOLTIP]Ranged Units[/TIP]. [B]-1 [icon:YIELD_GOLD][/B] [TIP:LOC_PEDIA_CONCEPTS_MAINTENANCE_TOOLTIP]Maintenance[/TIP] for Units."),
    ("en_US", "LOC_TRADITION_CHARTERS_DESCRIPTION", "[B]+2 [icon:YIELD_GOLD] Gold[/B] in all Settlements and [B]+1 [icon:YIELD_GOLD] Gold[/B] from [icon:SPECIALIST] [TIP:LOC_PEDIA_CONCEPTS_SPECIALIST_TOOLTIP]Specialists[/TIP]."),
    ("en_US", "LOC_TRADITION_UPOSATHA_DESCRIPTION", "[B]+2 [icon:YIELD_HAPPINESS] Happiness[/B] in all Settlements and [B]+1 [icon:YIELD_HAPPINESS] Happiness[/B] from [icon:SPECIALIST] [TIP:LOC_PEDIA_CONCEPTS_SPECIALIST_TOOLTIP]Specialists[/TIP]."),
    ("en_US", "LOC_TRADITION_INDENTURE_DESCRIPTION", "[B]+2 [icon:YIELD_FOOD] Food[/B] in all Settlements and [B]+1 [icon:YIELD_FOOD] Food[/B] from [icon:SPECIALIST] [TIP:LOC_PEDIA_CONCEPTS_SPECIALIST_TOOLTIP]Specialists[/TIP]."),

-- City-State
    ("en_US", "LOC_IMPROVEMENT_STONE_HEAD_DESCRIPTION", "Cultural City-State [TIP:LOC_PEDIA_CONCEPTS_UNIQUE_IMPROVEMENT_TOOLTIP]Unique Improvement[/TIP]. +2 [icon:YIELD_CULTURE] Culture. [TIP:LOC_PEDIA_CONCEPTS_AGELESS_TOOLTIP]Ageless[/TIP]. Must be placed on a tile with Charming or better Appeal."),
    ("en_US", "LOC_CITY_STATE_BONUS_EXPLORATION_6_DESCRIPTION", "Allows the construction of the Stone Head Unique Improvement. [n]The Stone Head provides +2 [icon:YIELD_CULTURE] Culture. Must be placed on a tile with Charming or better Appeal."),
    ("en_US", "LOC_IMPROVEMENT_MONASTERY_DESCRIPTION", "Scientific City-State [TIP:LOC_PEDIA_CONCEPTS_UNIQUE_IMPROVEMENT_TOOLTIP]Unique Improvement[/TIP]. +3 [icon:YIELD_SCIENCE] Science and +2 [icon:YIELD_HAPPINESS] Happiness if this Settlement follows your Religion. [TIP:LOC_PEDIA_CONCEPTS_AGELESS_TOOLTIP]Ageless[/TIP]."),
    ("en_US", "LOC_IMPROVEMENT_MONASTERY_TOOLTIP", "Effect: +2 [icon:YIELD_HAPPINESS] Happiness if this Settlement follows your Religion.[n]Does not remove [icon:YIELD_WAREHOUSE] [TIP:LOC_PEDIA_CONCEPTS_WAREHOUSE_TOOLTIP]Warehouse[/TIP] bonuses on a tile.[n]City-State [TIP:LOC_PEDIA_CONCEPTS_UNIQUE_IMPROVEMENT_TOOLTIP]Unique Improvement[/TIP]."),
    ("en_US", "LOC_CITY_STATE_BONUS_EXPLORATION_16_DESCRIPTION", "Allows the construction of the Monastery Unique Improvement. [n]The Monastery provides +3 [icon:YIELD_SCIENCE] Science and +2 [icon:YIELD_HAPPINESS] Happiness if its Settlement follows your Religion."),
    ("en_US", "LOC_IMPROVEMENT_KASBAH_DESCRIPTION", "Militaristic City-State [TIP:LOC_PEDIA_CONCEPTS_UNIQUE_IMPROVEMENT_TOOLTIP]Unique Improvement[/TIP]. +1 [icon:YIELD_CULTURE] Culture, +1 [icon:YIELD_GOLD] Gold, and +1 [icon:YIELD_SCIENCE] Science. [TIP:LOC_PEDIA_CONCEPTS_AGELESS_TOOLTIP]Ageless[/TIP]. Can be built in any biome, but cannot be adjacent to another Kasbah."),
    ("en_US", "LOC_IMPROVEMENT_KASBAH_TOOLTIP", "Does not remove [icon:YIELD_WAREHOUSE] [TIP:LOC_PEDIA_CONCEPTS_WAREHOUSE_TOOLTIP]Warehouse[/TIP] bonuses on a tile. Can be built in any biome, but cannot be adjacent to another Kasbah.[n]City-State [TIP:LOC_PEDIA_CONCEPTS_UNIQUE_IMPROVEMENT_TOOLTIP]Unique Improvement[/TIP]."),
    ("en_US", "LOC_CITY_STATE_BONUS_EXPLORATION_1_DESCRIPTION", "Allows the construction of the Kasbah Unique Improvement. [n]The Kasbah provides +1 [icon:YIELD_CULTURE] Culture, +1 [icon:YIELD_GOLD] Gold, and +1 [icon:YIELD_SCIENCE] Science. Can be built in any biome, but cannot be adjacent to another Kasbah."),
    ("en_US", "LOC_IMPROVEMENT_SAQIYA_DESCRIPTION", "Expansionist City-State [TIP:LOC_PEDIA_CONCEPTS_UNIQUE_IMPROVEMENT_TOOLTIP]Unique Improvement[/TIP]. +4 [icon:YIELD_FOOD] Food. [TIP:LOC_PEDIA_CONCEPTS_AGELESS_TOOLTIP]Ageless[/TIP]. Must be placed adjacent to a river."),
    ("en_US", "LOC_IMPROVEMENT_SAQIYA_TOOLTIP", "Does not remove [icon:YIELD_WAREHOUSE] [TIP:LOC_PEDIA_CONCEPTS_WAREHOUSE_TOOLTIP]Warehouse[/TIP] bonuses on a tile. Must be placed adjacent to a river.[n]City-State [TIP:LOC_PEDIA_CONCEPTS_UNIQUE_IMPROVEMENT_TOOLTIP]Unique Improvement[/TIP]."),
    ("en_US", "CITY_STATE_EXPANSIONIST_BONUS_EXPLORATION_1_DESCRIPTION", "Allows the construction of the Saqiya Unique Improvement. [n]The Saqiya provides +4 [icon:YIELD_FOOD] Food and must be placed adjacent to a river.");
